mapper.select:
SELECT

FROM workposition w
LEFT JOIN department d ON w.department_id = d.id AND d.delflag = 0 AND d.tenant_id = w.tenant_id
LEFT JOIN employee ec ON w.created_by = ec.id AND ec.delflag = 0 AND ec.tenant_id = w.tenant_id
LEFT JOIN employee eu ON w.updated_by = eu.id AND eu.delflag = 0 AND eu.tenant_id = w.tenant_id
WHERE w.id IN (
    SELECT DISTINCT wp.id FROM workposition wp
    INNER JOIN employee e ON e.position_id = wp.id
    INNER JOIN users u ON u.employee_id = e.id
    WHERE u.id = #{userId} AND u.tenant_id = #{tenantId}
    AND e.employment_status = 1 AND e.delflag = 0 AND e.tenant_id = #{tenantId}
    AND wp.delflag = 0 AND wp.tenant_id = #{tenantId}
)
AND w.delflag = 0 AND w.tenant_id = #{tenantId}
ORDER BY w.sort_order ASC

SELECT COUNT(1)
FROM workposition
WHERE name = #{name}
AND department_id = #{departmentId}
AND delflag = 0
AND tenant_id = #{tenantId}

    AND id != #{excludeId}

